import assert from 'node:assert/strict';
import fs from 'node:fs/promises';

export async function runMotionSearchSmoke(page){
 const viewport=page.viewport(),previous=await page.evaluate(()=>({project:JSON.stringify(project),curPage,curSec,curEl,curPane,selection,secFocus,mode:NAGWEB_STORY_EDITOR.canvasMode(),timeline:NAGWEB_STORY_TIMELINE_UI.state()}));
 try{
  await page.evaluate(()=>{delete project.nwMotionLibrary;const outside=mkEl('label',{name:'Exterior',text:'Fuera de Motion Lab'});project.pages[0].sections=[mkSection({layout:'free',sdEnabled:false,elements:[outside]})];curPage=0;curSec=0;curEl=0;selection=[outside.id];secFocus=false;saveProject();renderPane();renderPreview();history=[];future=[];});
  const before=await page.evaluate(()=>({project:JSON.stringify(project),stored:localStorage.getItem(STORE_KEY)}));
  async function ready(text,id){await page.waitForFunction(({text,id})=>{const d=document.querySelector('.nw-motion-dialog iframe')?.contentDocument;return d?.querySelector('[data-motion-canvas]')&&(!text||d.querySelector('.hd')?.textContent===text)&&(!id||d.querySelector('[data-id="'+id+'"]'));},{},{text,id});}
  async function search(value){await page.click('[data-motion-library-search]');await page.keyboard.down('Control');await page.keyboard.press('A');await page.keyboard.up('Control');await page.keyboard.type(value);}
  async function results(){return page.$$eval('[data-motion-template]',ns=>ns.filter(n=>!n.hidden&&!n.closest('.nw-motion-saved-item')?.hidden).map(n=>n.dataset.motionTemplate));}
  async function probe(){return page.$eval('.nw-motion-dialog iframe',f=>({marker:f.contentDocument.body.dataset.searchProbe,heading:f.contentDocument.querySelector('.hd').textContent,selected:f.contentDocument.querySelector('.nw-motion-selected')?.dataset.id}));}
  await page.click('.tb-left [data-motion-open]');await ready();const all=await results();assert.deepEqual(all,['iso-focus','soft-orbit','card-tunnel','card-bloom','showcase-stream','iso-orbit','pop-grid','center-stage','orbit-bloom','ticker-tilt','ticker-loop','carousel-flow','stack-slide','iso-focus-sequence','card-toss','diagonal-carousel','iso-cascade','grid-reveal','zoom-parallax','cascade-drop','focus-shift','spiral-stream','film-strip','card-totem','deck-peel','poster-burst','photo-orbit','wheel-carousel','wheel-spin','wheel-spin-bottom','cover-flow','cover-flow-vertical','cover-ring','cover-ring-vertical','image-trail','position-dance','cascade-deck','orbit-showcase','split-reveal','diagonal-wipe','stripe-reveal','mosaic-wipe','hero-reel','flip-grid','orbit-carousel','column-drift']);
  await page.click('[data-motion-library-tab="elements"]');const heading=await page.$eval('[data-motion-layer]:nth-child(5)',n=>n.dataset.motionLayer);await page.click('[data-motion-layer="'+heading+'"]');await page.click('[data-motion-content="4"]');await page.keyboard.down('Control');await page.keyboard.press('A');await page.keyboard.up('Control');await page.keyboard.type('Mi portada');await page.keyboard.press('Tab');await ready('Mi portada');await page.click('[data-motion-library-tab="library"]');await page.$eval('[data-motion-progress]',n=>{n.value='37.5';n.dispatchEvent(new Event('input',{bubbles:true}));});await page.$eval('.nw-motion-dialog iframe',f=>f.contentDocument.body.dataset.searchProbe='unchanged');const prepared=await probe();
  await search('ORBITA suave');assert.deepEqual(await results(),['soft-orbit']);assert.equal(await page.$eval('[data-motion-search-status]',n=>n.textContent),'1 composición');assert.deepEqual(await probe(),prepared);assert.equal(await page.$eval('[data-motion-progress]',n=>n.value),'37.5');await page.keyboard.press('Enter');assert.equal(await page.$eval('.nw-motion-dialog',n=>n.open),true);assert.deepEqual(await probe(),prepared,'Searching and Enter do not select or regenerate a template');
  await search('suave órbita');assert.deepEqual(await results(),['soft-orbit'],'All words match independent of order and accents');await search('carousel diagonal');assert.deepEqual(await results(),['diagonal-carousel']);await search('ISO cascade');assert.deepEqual(await results(),['iso-cascade']);await search('hero reel');assert.deepEqual(await results(),['hero-reel']);await search('mosaic wipe');assert.deepEqual(await results(),['mosaic-wipe']);await search('stripe reveal');assert.deepEqual(await results(),['stripe-reveal']);await search('diagonal wipe');assert.deepEqual(await results(),['diagonal-wipe']);await search('split reveal');assert.deepEqual(await results(),['split-reveal']);await search('orbit showcase');assert.deepEqual(await results(),['orbit-showcase']);await search('cascade deck');assert.deepEqual(await results(),['cascade-deck']);await search('position dance');assert.deepEqual(await results(),['position-dance']);await search('image trail');assert.deepEqual(await results(),['image-trail']);await search('cover ring');assert.deepEqual(await results(),['cover-ring','cover-ring-vertical']);await search('cover ring vertical');assert.deepEqual(await results(),['cover-ring-vertical']);await search('cover flow');assert.deepEqual(await results(),['cover-flow','cover-flow-vertical']);await search('cover flow vertical');assert.deepEqual(await results(),['cover-flow-vertical']);await search('wheel spin bottom');assert.deepEqual(await results(),['wheel-spin-bottom']);await search('wheel spin');assert.deepEqual(await results(),['wheel-spin','wheel-spin-bottom']);await search('wheel carousel');assert.deepEqual(await results(),['wheel-carousel']);await search('photo orbit');assert.deepEqual(await results(),['photo-orbit']);await search('poster burst');assert.deepEqual(await results(),['poster-burst']);await search('deck peel');assert.deepEqual(await results(),['deck-peel']);await search('film strip');assert.deepEqual(await results(),['film-strip']);await search('totem card');assert.deepEqual(await results(),['card-totem']);await search('spiral stream');assert.deepEqual(await results(),['spiral-stream']);await search('shift focus');assert.deepEqual(await results(),['focus-shift']);await search('drop cascade');assert.deepEqual(await results(),['cascade-drop']);await search('parallax zoom');assert.deepEqual(await results(),['zoom-parallax']);await search('reveal grid');assert.deepEqual(await results(),['grid-reveal']);await search('TOSS card');assert.deepEqual(await results(),['card-toss']);await search('ISO focus');assert.deepEqual(await results(),['iso-focus-sequence']);await search('láminas foco');assert.deepEqual(await results(),['iso-focus']);await search('TUNEL');assert.deepEqual(await results(),['card-tunnel']);await search('recorrido');assert.deepEqual(await results(),['card-tunnel','ticker-loop'],'Descriptions are searchable');await search('profundidad');assert.deepEqual(await results(),['soft-orbit','card-tunnel','card-bloom','orbit-carousel']);await search('[.*]');assert.deepEqual(await results(),[]);assert.match(await page.$eval('[data-motion-search-status]',n=>n.textContent),/Sin coincidencias/);assert.deepEqual(await probe(),prepared);assert.equal(await page.$eval('[data-motion-insert-group]',n=>n.disabled),false);
  await page.keyboard.press('Escape');assert.equal(await page.$eval('.nw-motion-dialog',n=>n.open),true,'First Escape clears the search rather than discarding the draft');assert.equal(await page.$eval('[data-motion-library-search]',n=>n.value),'');assert.deepEqual(await results(),all);assert.equal(await page.$eval('[data-motion-search-status]',n=>n.hidden),true);assert.equal(await page.$eval('[data-motion-search-clear]',n=>n.disabled),true);assert.deepEqual(await probe(),prepared);
  await search('órbita');await page.click('[data-motion-template="soft-orbit"]');await ready('Diseño en movimiento.');assert.equal(await page.$eval('[data-motion-library-search]',n=>n.value),'órbita');await page.click('[data-motion-search-clear]');assert.equal(await page.$eval('[data-motion-library-search]',n=>n===document.activeElement),true);await page.click('[data-motion-template="iso-focus"]');await ready('Mi portada',heading);assert.equal(await page.$eval('[data-motion-progress]',n=>n.value),'37.5');assert.equal((await probe()).selected,heading,'Switching matching templates retains the existing prepared draft and selection');
  // Filtering also leaves the single preview clock running.
  await page.click('[data-motion-play]');const start=await page.$eval('[data-motion-progress]',n=>n.value);await search('inexistente');assert.equal(await page.$eval('[data-motion-play]',n=>n.getAttribute('aria-pressed')),'true');await page.waitForFunction(start=>document.querySelector('[data-motion-progress]').value!==start,{timeout:3000},start);await page.click('[data-motion-search-clear]');assert.equal(await page.$eval('[data-motion-play]',n=>n.getAttribute('aria-pressed')),'true');await page.click('[data-motion-play]');assert.equal(await page.evaluate(()=>JSON.stringify(project)),before.project);assert.equal(await page.evaluate(()=>localStorage.getItem(STORE_KEY)),before.stored);assert.equal(await page.evaluate(()=>history.length),0);
  // Rebuilding the saved cards reapplies the query without touching the current draft.
  await search('orbita');await page.click('[data-motion-library-name]');await page.keyboard.type('Mi Órbita <b>personal</b>');await page.click('[data-motion-library-save]');const saved=await page.evaluate(()=>project.nwMotionLibrary[0]);assert.deepEqual(await results(),['soft-orbit','photo-orbit','orbit-showcase',saved.id]);assert.equal(await page.$eval('[data-motion-search-status]',n=>n.textContent),'4 composiciones');await search('<b>');assert.deepEqual(await results(),[saved.id]);assert.equal(await page.$('[data-motion-saved="'+saved.id+'"] strong b'),null);assert.equal(await page.$eval('[data-motion-saved="'+saved.id+'"] strong',n=>n.textContent),saved.name);assert.equal((await probe()).heading,'Mi portada');
  const savedProject=await page.evaluate(()=>JSON.stringify(project));await page.click('[data-motion-library-remove="'+saved.id+'"]');assert.deepEqual(await results(),[]);assert.match(await page.$eval('[data-motion-search-status]',n=>n.textContent),/Sin coincidencias/);assert.equal(await page.$eval('[data-motion-library-search]',n=>n.value),'<b>');await page.click('[data-motion-close]');await page.evaluate(()=>undo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),savedProject);
  await page.click('.tb-left [data-motion-open]');await ready();assert.equal(await page.$eval('[data-motion-library-search]',n=>n.value),'','A new session opens the full library');assert.deepEqual(await results(),[...all,saved.id]);await search('PERSONAL orbita');assert.deepEqual(await results(),[saved.id]);await page.click('[data-motion-saved="'+saved.id+'"]');const copy=await page.$eval('[data-motion-layer]:nth-child(5)',n=>n.dataset.motionLayer);await ready('Mi portada',copy);await page.click('[data-motion-insert-group]');const inserted=await page.evaluate(()=>{const g=sec().elements.find(e=>e.nwMotionInstance);return {gid:g.id,project:JSON.stringify(project)};});
  await page.evaluate(id=>NAGWEB_MOTION_LAB.edit(id),inserted.gid);await ready('Mi portada');assert.equal(await page.$eval('[data-motion-library-search]',n=>n.value),'');await search('tunel');assert.deepEqual(await results(),['card-tunnel']);assert.equal(await page.$eval('[data-motion-template="card-tunnel"]',n=>n.disabled),true);await page.click('[data-motion-close]');assert.equal(await page.evaluate(()=>JSON.stringify(project)),inserted.project,'Searching while editing an instance never applies changes');
  await page.setViewport({width:390,height:844,deviceScaleFactor:1});await page.evaluate(()=>NAGWEB_MOTION_LAB.open());await ready();await search('abanico');assert.deepEqual(await results(),['card-bloom']);assert.ok(await page.$eval('[data-motion-library-search]',n=>{const r=n.getBoundingClientRect();return r.left>=0&&r.right<=innerWidth;}));await page.click('[data-motion-template="card-bloom"]');await ready('Miradas que se despliegan.');assert.ok(await page.$eval('.nw-motion-dialog iframe',f=>{const d=f.contentDocument;return d.querySelector('.hd').getBoundingClientRect().top>=d.querySelector('.lbl').getBoundingClientRect().bottom+4;}),'Wrapped fan heading stays below the label on compact screens');await fs.mkdir('/tmp/nagweb-motion-visuals',{recursive:true});await (await page.$('.nw-motion-dialog')).screenshot({path:'/tmp/nagweb-motion-visuals/search-mobile.png'});await page.click('[data-motion-search-clear]');assert.deepEqual(await results(),[...all,saved.id]);await page.click('[data-motion-close]');assert.equal(await page.evaluate(()=>JSON.stringify(project)),inserted.project);
  console.log('Buscar Motion Lab: teclado real, nombres/descripciones sin tildes y palabras en cualquier orden, búsqueda literal segura, vacío/sin coincidencias, Escape y limpiar con foco, mismo iframe/selección/pose, borradores y reproducción intactos, altas/bajas e historial de Biblioteca, nueva sesión, instancia y móvil sin escrituras OK');
 }finally{
  await page.setViewport(viewport);await page.evaluate(p=>{document.querySelector('.nw-motion-dialog').close();clearTimeout(previewTimer);project=JSON.parse(p.project);curPage=p.curPage;curSec=p.curSec;curEl=p.curEl;curPane=p.curPane;selection=p.selection;secFocus=p.secFocus;history=[];future=[];NAGWEB_STORY_EDITOR.setCanvasMode(p.mode);NAGWEB_STORY_TIMELINE_UI.setState(p.timeline);saveProject();renderScenes();renderPane();renderPreview();},previous);
 }
}
